    display: block;
    max-width: 100vw;
    max-height: 100vh;
    background: #2b2420;
    image-rendering: auto;
    touch-action: none;
    outline: none;
  }
  /* Faults: hidden until something goes wrong, then readable text on a dark banner. */
  #errors {
    display: none;
    position: fixed;
