  if (!blocked(city, ped.x, ny, 7)) ped.y = ny;
  if (ped.x < CELL || ped.x > city.size - CELL || ped.y < CELL || ped.y > BEACH_Y - CELL) {
    ped.x = clamp(ped.x, CELL, city.size - CELL);
    ped.y = clamp(ped.y, CELL, BEACH_Y - CELL);
