  function drawPalms(state) {
    const palms = state.city.palms;
    for (let i = 0; i < palms.length; i += 1) {
      const p = palms[i];
      const s = p.scale || 1;
      if (!visiblePoint(p.x, p.y, 70 * s)) continue;
      ctx.fillStyle = C.shadow;
      ctx.beginPath();
      ctx.ellipse(p.x + 26 * s, p.y + 16 * s, 34 * s, 9 * s, -0.35, 0, Math.PI * 2);
