      ctx.fillStyle = '#2f3033';
      ctx.fillRect(bb.x - 3, bb.y - 3, bb.w + 6, bb.h + 6);
      ctx.fillRect(bb.x + bb.w * 0.5 - 2, bb.y + bb.h, 4, 14);
      ctx.fillStyle = bb.bg || '#f7efe0';
      ctx.fillRect(bb.x, bb.y, bb.w, bb.h);
