      ctx.fillStyle = 'rgba(255, 236, 200, 0.22)';
      ctx.beginPath();
      ctx.moveTo(bb.x, bb.y + bb.h);
      ctx.lineTo(bb.x + bb.w * 0.55, bb.y);
      ctx.lineTo(bb.x + bb.w * 0.8, bb.y);
      ctx.lineTo(bb.x + bb.w * 0.25, bb.y + bb.h);
