  // -------------------------------------------------------------------------------------------
  // Agents: peds, traffic, police and officers, bullets, particles, then the player.
  // -------------------------------------------------------------------------------------------
  function drawPeds(state) {
    const peds = state.peds;
    if (!peds) return;
    for (let i = 0; i < peds.length; i += 1) {
      const p = peds[i];
      if (!visiblePoint(p.x, p.y, 20)) continue;
